def main():
    print("Loading existing KEV records...")
    existing = []
    if KEV_FILE.exists():
        with open(KEV_FILE, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if line:
                    try:
                        existing.append(json.loads(line))
                    except:
                        pass
    print(f"Found {len(existing)} existing records.")

    print(f"Adding {len(NEW_RECORDS)} new high-quality KEV exploitation records...")
    all_records = existing + NEW_RECORDS

    # Write back
    with open(KEV_FILE, "w", encoding="utf-8") as f:
        for rec in all_records:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")

    print(f"✅ Written {len(all_records)} total records to {KEV_FILE}")
    print("New records added with source_ids kev-009 through kev-019 (and earlier ones preserved).")

if __name__ == "__main__":
    main()
